export const ABILITIES: Ability[] = RAW_ABILITIES.map((row) => ({
  id: row[0],
  name: row[1],
  tier: row[2],
  classLabel: row[3],
  baseClass: row[4],
  kind: row[5],
  cost: row[6],
  cooldown: row[7],
  power: row[8],
  range: row[9],
  aoeRadius: row[10],
  description: row[11],
  tags: row[12] ?? [],
  evolvingBySubclass: EVOLVING_VARIANTS[row[0]],
  paradoxKey: row[13],
}));

export function getAbilityById(id: number): Ability | undefined {
  return ABILITIES.find((a) => a.id === id);
}
